<script setup lang="ts">
/**
 * Single-value choice from a closed list (`design/components/select.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/select.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import * as zag from '@zag-js/select'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  Icon,
  agentMember,
  fieldLabelIds,
  followHighlight,
  returnFocus,
  useDirection,
  useMediaQuery,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/controls/select.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'

export interface SelectOption {
  value: string
  label: string
  description?: string
  disabled?: boolean
}

export interface SelectOptionGroup {
  label: string
  options: SelectOption[]
}

export interface SelectProps {
  ariaDescribedby?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  ariaLabel?: string
  /**
   * Names the field from a label elsewhere on the page, such as `SettingsRow`'s row label, which
   * is one label for a whole row rather than one per control.
   */
  ariaLabelledby?: string
  ariaRequired?: boolean
  /**
   * Opens on mount. For galleries and tests; screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: string | null
  disabled?: boolean
  /**
   * Labels a selectable empty choice, always rendered as the **first** item. Choosing it reports
   * `null`. The trigger then shows this label as a real value, because "All" is a chosen state,
   * not a missing value.
   */
  emptyOption?: string
  id?: string
  invalid?: boolean
  name?: string
  /**
   * Flat, grouped, or mixed. `emptyOption` stays first and belongs to no group.
   */
  options: (SelectOption | SelectOptionGroup)[]
  /**
   * Muted, and shown only until there is a value. Cannot be combined with `emptyOption`.
   */
  placeholder?: string
  /**
   * `'auto'` shows the panel as a sheet below `30rem` (the conventions' sheet presentation, the
   * usual phone pattern for choosing from a list). `'popover'` keeps the popper at every width,
   * for the rare pointer-first case that needs precision. There is no always-sheet value,
   * because a bottom sheet on a wide pointer screen is the wrong pattern (`docs/layout.md`).
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * The chosen option's value. Controlled when given. `null` is nothing chosen: the trigger
   * shows the placeholder, or the empty choice when `emptyOption` is set. A caller clears the
   * choice with `null`, because `undefined` is no value, which hands the choice back to the
   * member.
   */
  value?: string | null
}

defineOptions({ name: 'Select', inheritAttrs: false })

const props = withDefaults(defineProps<SelectProps>(), {
  ariaRequired: undefined,
  defaultOpen: undefined,
  disabled: false,
  invalid: false,
  presentation: 'auto',
  size: 'md',
})
const emit = defineEmits<{ change: [value: string | null] }>()
const uid = useId()
const fieldLabels = ref(undefined as string | undefined)
const panel = useTemplateRef<HTMLElement>('panel')
const scrim = useTemplateRef<HTMLElement>('scrim')
const sheetPanel = useTemplateRef<HTMLElement>('sheetPanel')
const trigger = useTemplateRef<HTMLElement>('trigger')
const phone = useMediaQuery('phone')
const sheeting = computed(() => props.presentation === 'auto' && phone.value)
const unnamed = computed(() => props.ariaLabel === undefined && props.ariaLabelledby === undefined)
const emptyChoice = computed(() => ({
  value: '__polymorph-empty-choice__',
  label: props.emptyOption ?? '',
  description: undefined,
  disabled: false,
}))
const flat = computed(() => [
  ...(props.emptyOption === undefined ? [] : [emptyChoice.value]),
  ...props.options.flatMap((entry) => ('options' in entry ? entry.options : [entry])),
])
const documentDirection = useDirection(() => trigger.value)
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    collection: zag.collection({
      items: flat.value,
      itemToValue: (item) => item.value,
      itemToString: (item) => item.label,
      isItemDisabled: (item) => item.disabled === true,
    }),
    value:
      props.value === undefined
        ? undefined
        : props.value === null
          ? props.emptyOption === undefined
            ? []
            : ['__polymorph-empty-choice__']
          : [props.value],
    defaultValue:
      props.defaultValue === undefined && props.emptyOption !== undefined
        ? ['__polymorph-empty-choice__']
        : props.defaultValue === undefined
          ? undefined
          : props.defaultValue === null
            ? props.emptyOption === undefined
              ? []
              : ['__polymorph-empty-choice__']
            : [props.defaultValue],
    defaultOpen: props.defaultOpen,
    disabled: props.disabled,
    invalid: props.invalid,
    positioning: { placement: 'bottom-start' as const, gutter: 2 },
    ids: props.id === undefined ? undefined : { trigger: props.id },
    onValueChange: (details) => {
      emit(
        'change',
        details.value[0] === undefined || details.value[0] === '__polymorph-empty-choice__'
          ? null
          : details.value[0],
      )
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const shown = computed(() => flat.value.find((choice) => api.value.value.includes(choice.value)))
const placeholderShown = computed(() => shown.value === undefined)
const present = usePresence(() => api.value.open && !sheeting.value, panel)
const sheetPresent = usePresence(
  () => api.value.open && sheeting.value,
  sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(() => api.value.open && sheeting.value, scrim, 'dialog.scrim')
const effect1 = () => {
  api.value.open &&
    api.value.highlightedValue === null &&
    api.value.setHighlightValue(
      api.value.value[0] ?? flat.value.find((choice) => !choice.disabled)?.value ?? '',
    )
}
onMounted(effect1)
watch(() => api.value.open, effect1, { flush: 'post' })
const effect2 = () => {
  api.value.open || returnFocus(trigger.value, panel.value)
}
watch(() => api.value.open, effect2, { flush: 'post' })
const effect3 = () => {
  followHighlight(panel.value, api.value.highlightedValue)
}
onMounted(effect3)
watch(() => api.value.highlightedValue, effect3, { flush: 'post' })
const effect4 = () => {
  api.value.open && unnamed.value && (fieldLabels.value = fieldLabelIds(trigger.value, uid))
}
onMounted(effect4)
watch(() => api.value.open && unnamed.value, effect4, { flush: 'post' })
let release5: (() => void) | undefined
const effect5 = () => {
  release5?.()
  const ran = agentMember({
    member: 'Select',
    element: () => trigger.value,
    state: () => ({
      value:
        api.value.value[0] === undefined
          ? props.emptyOption === undefined
            ? null
            : ''
          : api.value.value[0] === '__polymorph-empty-choice__'
            ? ''
            : api.value.value[0],
      options: flat.value.map((choice) => ({
        id: choice.value === '__polymorph-empty-choice__' ? '' : choice.value,
        label: choice.label,
        ...(choice.disabled === true ? { disabled: true } : {}),
      })),
      open: api.value.open,
      disabled: props.disabled,
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) => api.value.setValue([value === '' ? '__polymorph-empty-choice__' : value]),
      },
      open: () => api.value.setOpen(true),
      close: () => api.value.setOpen(false),
    },
  })
  release5 = () => {
    ran()
  }
}
onMounted(effect5)
onBeforeUnmount(() => release5?.())
</script>

<template>
  <button
    ref="trigger"
    v-bind="api.getTriggerProps()"
    :class="styles.trigger"
    :aria-label="ariaLabel"
    :aria-labelledby="ariaLabelledby"
    :aria-describedby="ariaDescribedby"
    :aria-required="ariaRequired"
    :aria-invalid="invalid ? true : undefined"
    :data-size="size"
    :data-invalid="invalid ? '' : undefined"
    :data-disabled="disabled ? '' : undefined"
    :data-placeholder="placeholderShown ? '' : undefined"
    data-member="select"
  >
    <span :class="styles.value">
      {{ shown?.label ?? (emptyOption === undefined ? (placeholder ?? '') : '') }}
    </span>
    <span :class="styles.chevron" aria-hidden="true">
      <Icon name="expand" :size="size" />
    </span>
  </button>
  <input
    v-if="name !== undefined"
    type="hidden"
    :name="name"
    :value="
      api.value[0] === undefined || api.value[0] === '__polymorph-empty-choice__'
        ? ''
        : api.value[0]
    "
    :disabled="disabled || undefined"
  />
  <Teleport to="body">
    <div v-if="present" v-bind="api.getPositionerProps()">
      <!-- panel -->
      <div
        ref="panel"
        v-bind="api.getContentProps()"
        :class="styles.content"
        :style="{
          '--radix-select-trigger-width': 'var(--reference-width)',
          '--radix-select-content-available-height': 'var(--available-height)',
          '--radix-select-content-transform-origin': 'var(--transform-origin)',
        }"
        :hidden="undefined"
        :aria-label="ariaLabelledby === undefined ? ariaLabel : undefined"
        :aria-labelledby="unnamed ? fieldLabels : ariaLabelledby"
        :data-size="size"
        data-member="select"
        @focus="followHighlight(panel, api.highlightedValue)"
      >
        <div :class="styles.viewport">
          <!-- option -->
          <div
            v-if="emptyOption !== undefined"
            v-bind="api.getItemProps({ item: emptyChoice })"
            :class="styles.item"
            tabindex="-1"
            @focus="api.setHighlightValue(emptyChoice.value)"
          >
            <span :class="styles.check">
              <Icon v-if="api.value.includes(emptyChoice.value)" name="confirm" size="sm" />
            </span>
            <span :class="styles.text">
              <span>
                {{ emptyChoice.label }}
              </span>
              <span v-if="emptyChoice.description !== undefined" :class="styles.description">
                {{ emptyChoice.description }}
              </span>
            </span>
          </div>
          <template
            v-for="entry in options"
            :key="'options' in entry ? `group-${entry.label}` : entry.value"
          >
            <div
              v-if="'options' in entry"
              v-bind="api.getItemGroupProps({ id: entry.label })"
              :class="styles.group"
            >
              <div
                v-bind="api.getItemGroupLabelProps({ htmlFor: entry.label })"
                :class="styles.groupLabel"
              >
                {{ entry.label }}
              </div>
              <template v-for="choice in entry.options" :key="choice.value">
                <!-- option -->
                <div
                  v-bind="api.getItemProps({ item: choice })"
                  :class="styles.item"
                  tabindex="-1"
                  @focus="api.setHighlightValue(choice.value)"
                >
                  <span :class="styles.check">
                    <Icon v-if="api.value.includes(choice.value)" name="confirm" size="sm" />
                  </span>
                  <span :class="styles.text">
                    <span>
                      {{ choice.label }}
                    </span>
                    <span v-if="choice.description !== undefined" :class="styles.description">
                      {{ choice.description }}
                    </span>
                  </span>
                </div>
              </template>
            </div>
            <!-- option -->
            <div
              v-else
              v-bind="api.getItemProps({ item: entry })"
              :class="styles.item"
              tabindex="-1"
              @focus="api.setHighlightValue(entry.value)"
            >
              <span :class="styles.check">
                <Icon v-if="api.value.includes(entry.value)" name="confirm" size="sm" />
              </span>
              <span :class="styles.text">
                <span>
                  {{ entry.label }}
                </span>
                <span v-if="entry.description !== undefined" :class="styles.description">
                  {{ entry.description }}
                </span>
              </span>
            </div>
          </template>
        </div>
      </div>
    </div>
    <div
      v-if="scrimPresent"
      ref="scrim"
      :class="sheet.scrim"
      :data-state="api.open ? 'open' : 'closed'"
    />
    <div v-if="sheetPresent" :class="sheet.positioner">
      <div
        ref="sheetPanel"
        :class="sheet.panel"
        data-presentation="sheet"
        :data-state="api.open ? 'open' : 'closed'"
        tabindex="-1"
      >
        <!-- panel -->
        <div
          ref="panel"
          v-bind="api.getContentProps()"
          :class="styles.sheetList"
          :hidden="undefined"
          :aria-label="ariaLabelledby === undefined ? ariaLabel : undefined"
          :aria-labelledby="unnamed ? fieldLabels : ariaLabelledby"
          :data-size="size"
          data-member="select"
          @focus="followHighlight(panel, api.highlightedValue)"
        >
          <!-- option -->
          <div
            v-if="emptyOption !== undefined"
            v-bind="api.getItemProps({ item: emptyChoice })"
            :class="styles.item"
            tabindex="-1"
            @focus="api.setHighlightValue(emptyChoice.value)"
          >
            <span :class="styles.check">
              <Icon v-if="api.value.includes(emptyChoice.value)" name="confirm" size="sm" />
            </span>
            <span :class="styles.text">
              <span>
                {{ emptyChoice.label }}
              </span>
              <span v-if="emptyChoice.description !== undefined" :class="styles.description">
                {{ emptyChoice.description }}
              </span>
            </span>
          </div>
          <template
            v-for="entry in options"
            :key="'options' in entry ? `group-${entry.label}` : entry.value"
          >
            <div
              v-if="'options' in entry"
              v-bind="api.getItemGroupProps({ id: entry.label })"
              :class="styles.group"
            >
              <div
                v-bind="api.getItemGroupLabelProps({ htmlFor: entry.label })"
                :class="styles.groupLabel"
              >
                {{ entry.label }}
              </div>
              <template v-for="choice in entry.options" :key="choice.value">
                <!-- option -->
                <div
                  v-bind="api.getItemProps({ item: choice })"
                  :class="styles.item"
                  tabindex="-1"
                  @focus="api.setHighlightValue(choice.value)"
                >
                  <span :class="styles.check">
                    <Icon v-if="api.value.includes(choice.value)" name="confirm" size="sm" />
                  </span>
                  <span :class="styles.text">
                    <span>
                      {{ choice.label }}
                    </span>
                    <span v-if="choice.description !== undefined" :class="styles.description">
                      {{ choice.description }}
                    </span>
                  </span>
                </div>
              </template>
            </div>
            <!-- option -->
            <div
              v-else
              v-bind="api.getItemProps({ item: entry })"
              :class="styles.item"
              tabindex="-1"
              @focus="api.setHighlightValue(entry.value)"
            >
              <span :class="styles.check">
                <Icon v-if="api.value.includes(entry.value)" name="confirm" size="sm" />
              </span>
              <span :class="styles.text">
                <span>
                  {{ entry.label }}
                </span>
                <span v-if="entry.description !== undefined" :class="styles.description">
                  {{ entry.description }}
                </span>
              </span>
            </div>
          </template>
        </div>
      </div>
    </div>
  </Teleport>
</template>
